function updateSkinCards(){const grid=$('#skinGrid');grid.innerHTML='';for(const s of skins){const open=unlocked.includes(s.id),active=selected===s.id,card=document.createElement('button');card.className=`skin-card${active?' selected':''}${open?'':' locked'}`;card.type='button';card.setAttribute('aria-label',`${s.name} shark ${open?'':'locked, costs '+s.cost+' pearls'}`);card.innerHTML=`<span class="check">✓</span><div class="skin-art">${miniShark(s)}</div><div class="skin-name">${s.name}</div><div class="skin-sub">${open?(active?'EQUIPPED':'READY'):`<span class="lock">✦ ${s.cost}</span>`}</div>`;card.onclick=()=>{if(open){selected=s.id;store.set('selected',selected);updateSkinCards();$('#currentSkin').textContent=s.name.toUpperCase()}else if(pearls>=s.cost){pearls-=s.cost;unlocked.push(s.id);store.set('pearls',pearls);store.set('unlocked',unlocked);store.set('selected',s.id);selected=s.id;syncWallet();updateSkinCards();toast(`${s.name.toUpperCase()} SKIN UNLOCKED`)}else toast(`NEED ${s.cost-pearls} MORE PEARLS TO UNLOCK`)};grid.append(card)}$('#skinCount').textContent=`${unlocked.length} / ${skins.length}`}
