function spawnMine(){let y=110+Math.random()*(H-220);entities.push({type:'mine',x:W+40,y,r:22,rot:Math.random()*6})}
function spawnFish(){let y=95+Math.random()*(H-190);entities.push({type:Math.random()<.54?'pearl':'fish',x:W+25,y,r:12,size:.72+Math.random()*.38,color:['#ffc46c','#80f0d7','#f89f9a'][Math.floor(Math.random()*3)]})}
