spawn-=dt;if(spawn<=0){spawnMine();spawn=Math.max(.68,1.36-distance/11000)*(0.7+Math.random()*.6)}fishSpawn-=dt;if(fishSpawn<=0){spawnFish();fishSpawn=.72+Math.random()*.65}
