if(e.type==='mine'){if(player.inv<=0){player.inv=1.2;shake=.3;burst(player.x,player.y,'#ff9b78',14);endGame();break}}
else{if(e.type==='pearl'){runPearls++;burst(e.x,e.y,'#f8e394',8)}else{score+=10;burst(e.x,e.y,e.color,6)}entities.splice(i,1);continue}}
if(e.x<-50)entities.splice(i,1)}
}
for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0)particles.splice(i,1)}
}
function frame(now){let dt=Math.min(.033,(now-last)/1000||0);last=now;update(dt);render(dt);requestAnimationFrame(frame)}requestAnimationFrame(frame);

