$('#playBtn').addEventListener('click',()=>{if(state==='paused'){state='play';$('#menu').classList.add('hidden')}else startGame()});
$('#againBtn').addEventListener('click',startGame);
$('#pauseBtn').addEventListener('click',()=>{if(state==='play')setPause();else if(state==='paused')setPause()});
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','Space'].includes(e.code))e.preventDefault();keys[e.code]=true;if((e.code==='KeyP'||e.code==='Escape')&&state==='play')setPause();if(e.code==='Enter'&&(state==='menu'||state==='result'))startGame()});window.addEventListener('keyup',e=>{keys[e.code]=false});window.addEventListener('blur',()=>{keys={};if(state==='play')setPause()});
function holdButton(id,code){const el=$(id);el.addEventListener('pointerdown',e=>{e.preventDefault();keys[code]=true;el.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>el.addEventListener(ev,()=>keys[code]=false))}
holdButton('#upBtn','ArrowUp');holdButton('#downBtn','ArrowDown');holdButton('#boostBtn','Space');
syncWallet();updateSkinCards();$('#currentSkin').textContent=skin().name.toUpperCase();
})();
</script></body></html>

